```tsx
import React from 'react';
import { Link } from 'react-router-dom';
import type { ActiveMentorship } from '../types';

interface ActiveMentorshipCardProps {
  mentorship: ActiveMentorship;
  userType: 'mentee' | 'mentor';
  onViewGoals?: (mentorship: ActiveMentorship) => void;
}

const ActiveMentorshipCard: React.FC<ActiveMentorshipCardProps> = ({ mentorship, userType, onViewGoals }) => {
    // Check if it's a program by checking for program specific properties or type
    const isProgram = mentorship.participant.title?.toLowerCase().includes('mentoring program') || !!mentorship.mentoringType;

    const engagementLink = isProgram 
        ? `/program-engagement/${mentorship.id}` 
        : `/mentor/engagement/${mentorship.id}`;

    // Get Business and Vertical from dossier if available
    const business = mentorship.participant.dossier?.business;
    const vertical = mentorship.participant.dossier?.function; // Using function as vertical or vertical field if added
    const hasBusinessInfo = business && vertical;

    return (
        <div className="bg-white p-4 rounded-lg shadow-sm border flex flex-col sm:flex-row justify-between items-start gap-4">
            <div className="flex items-start space-x-4 flex-grow">
                <img className="h-12 w-12 rounded-full" src={mentorship.participant.imageUrl} alt={mentorship.participant.name} />
                <div className="flex-grow">
                    <div className="flex flex-wrap items-center gap-2 mb-1">
                        <Link to={engagementLink} state={{ userRole: userType }}>
                            <div className="flex items-center gap-2">
                                <h3 className="font-heading font-semibold text-r-gray-800 hover:underline hover:text-r-blue-dark">
                                    {mentorship.participant.name}
                                </h3>
                                {/* Show Topic in bold next to name for 1:1 Mentorships */}
                                {!isProgram && (
                                    <span className="text-gray-900 font-bold text-sm">
                                        - {mentorship.topic}
                                    </span>
                                )}
                            </div>
                        </Link>

                        {/* Base Type Tag */}
                        <span className={`px-2 py-0.5 text-xs font-semibold rounded-full ${isProgram ? 'bg-purple-100 text-purple-800' : 'bg-blue-100 text-blue-800'}`}>
                            {isProgram ? 'Mentoring Program' : 'Open Mentoring'}
                        </span>

                        {/* Mentoring Type Tag (Group/One-on-One) - Show for programs */}
                        {mentorship.mentoringType && (
                             <span className="px-2 py-0.5 text-xs font-semibold rounded-full bg-indigo-100 text-indigo-800 border border-indigo-200">
                                {mentorship.mentoringType}
                             </span>
                        )}

                        {/* Program Type Tag (Open/Closed) - REMOVED for Programs as per requirement */}
                    </div>

                    <p className="text-sm text-r-gray-500">{mentorship.participant.title || mentorship.participant.grade}</p>

                    {/* Show Business and Vertical for 1:1 Mentorships */}
                    {!isProgram && hasBusinessInfo && (
                        <p className="text-xs text-r-gray-600 mt-1 font-medium">
                            {business} | {vertical}
                        </p>
                    )}
                </div>
            </div>
            <div className="w-full sm:w-auto flex flex-col items-start sm:items-end gap-3">
                <div className="flex items-center gap-2">
                    {userType === 'mentor' && mentorship.goals && mentorship.goals.length > 0 && (
                        <button
                            onClick={() => onViewGoals?.(mentorship)}
                            className="px-4 py-2 text-sm font-medium text-r-blue border border-r-blue rounded-full hover:bg-r-blue-50 transition-colors"
                        >
                            View Goals
                        </button>
                    )}
                    <Link 
                        to={engagementLink}
                        state={{ userRole: userType }}
                        className="px-4 py-2 text-sm font-medium text-white bg-r-blue rounded-full hover:bg-r-blue-dark transition-colors"
                    >
                        View Engagement
                    </Link>
                </div>
            </div>
        </div>
    );
};

export default ActiveMentorshipCard;
