                value={value} 
                onChange={(e) => onValueChange(parseInt(e.target.value) || 0)} 
                className="w-12 text-center text-sm border-x border-gray-300 py-1 focus:outline-none"
            />
            <button type="button" onClick={() => onValueChange(value + 1)} className="px-2 py-1 bg-gray-100 hover:bg-gray-200 text-gray-600">+</button>
